// ---------------------------------------------------------------------------------------------------------------------
// Concurrent benchmarks.
namespace
{
	FE::concurrent_memory_resource* g_concurrent_memory_resource = nullptr;
	std::pmr::synchronized_pool_resource* g_synchronized_pool_resource = nullptr;

	// This reads the framework, so it must NOT run during static initialization. That is why the benchmarks below
	// are registered from register_concurrent_benchmarks() at the bottom of this file instead of by the BENCHMARK
	// macro: the macro expands to a global scope static whose initializer runs before main(), at which point the
	// framework does not exist yet.
	int max_concurrency() noexcept
	{
		return static_cast<int>(FE::framework::framework_base::get_framework().get_program_options().get_max_concurrency());
	}

	void setup_concurrent_memory_resource(const benchmark::State&)
	{
		const auto& options = FE::framework::framework_base::get_framework().get_program_options();
		g_concurrent_memory_resource = new FE::concurrent_memory_resource(options.is_large_page_enabled(), options.get_max_concurrency());
	}

	void teardown_concurrent_memory_resource(const benchmark::State&)
	{
		delete g_concurrent_memory_resource;
		g_concurrent_memory_resource = nullptr;
	}

	void setup_synchronized_pool_resource(const benchmark::State&)
	{
		g_synchronized_pool_resource = new std::pmr::synchronized_pool_resource();
	}

	void teardown_synchronized_pool_resource(const benchmark::State&)
	{
		delete g_synchronized_pool_resource;
		g_synchronized_pool_resource = nullptr;
	}
}


