// ---------------------------------------------------------------------------------------------------------------------
// Runtime registration of everything above.
//
// BENCHMARK(x) expands to a global scope static, so its decorator arguments are evaluated during static
// initialization, before main(). ThreadRange(1, max_concurrency()) therefore reached into the framework before the
// framework was constructed. benchmark::RegisterBenchmark does the same job from ordinary code, so this function
// has to be called AFTER the framework is initialized and BEFORE benchmark::RunSpecifiedBenchmarks().
//
// The single threaded benchmarks earlier in the file keep their BENCHMARK macros: they touch the framework only
// inside their bodies, which run at benchmark time, not at registration time.
// ---------------------------------------------------------------------------------------------------------------------

// The reported names have to stay identical to the ones BENCHMARK(x) produced, so the name comes from the same
// stringised identifier rather than from a hand written string.
#define FE_REGISTER_CONCURRENT_BENCHMARK(function_p) benchmark::RegisterBenchmark(#function_p, function_p)

void register_concurrent_benchmarks() noexcept
{
	const int l_max_threads = max_concurrency();


	FE_REGISTER_CONCURRENT_BENCHMARK(new_delete_extreme_fixed_sized_accumulation_concurrent_test)
		->Iterations(1000)->ThreadRange(1, l_max_threads)->UseRealTime();

#if FE_HAS_TBB_SCALABLE_MEMORY_RESOURCE
	FE_REGISTER_CONCURRENT_BENCHMARK(tbb_scalable_memory_resource_extreme_fixed_sized_accumulation_concurrent_test)
		->Iterations(1000)->ThreadRange(1, l_max_threads)->UseRealTime();
#endif

	FE_REGISTER_CONCURRENT_BENCHMARK(std_pmr_synchronized_pool_resource_extreme_fixed_sized_accumulation_concurrent_test)
		->Setup(setup_synchronized_pool_resource)->Teardown(teardown_synchronized_pool_resource)
		->Iterations(1000)->ThreadRange(1, l_max_threads)->UseRealTime();

	FE_REGISTER_CONCURRENT_BENCHMARK(FE_CMR_extreme_fixed_sized_accumulation_concurrent_test)
		->Setup(setup_concurrent_memory_resource)->Teardown(teardown_concurrent_memory_resource)
		->Iterations(1000)->ThreadRange(1, l_max_threads)->UseRealTime();


	FE_REGISTER_CONCURRENT_BENCHMARK(new_delete_extreme_fixed_sized_concurrent_test)
		->Iterations(30000)->ThreadRange(1, l_max_threads)->UseRealTime();

#if FE_HAS_TBB_SCALABLE_MEMORY_RESOURCE
	FE_REGISTER_CONCURRENT_BENCHMARK(tbb_scalable_memory_resource_extreme_fixed_sized_concurrent_test)
		->Iterations(30000)->ThreadRange(1, l_max_threads)->UseRealTime();
#endif

	FE_REGISTER_CONCURRENT_BENCHMARK(std_pmr_synchronized_pool_resource_extreme_fixed_sized_concurrent_test)
		->Setup(setup_synchronized_pool_resource)->Teardown(teardown_synchronized_pool_resource)
		->Iterations(30000)->ThreadRange(1, l_max_threads)->UseRealTime();

	FE_REGISTER_CONCURRENT_BENCHMARK(FE_CMR_extreme_fixed_sized_concurrent_test)
		->Setup(setup_concurrent_memory_resource)->Teardown(teardown_concurrent_memory_resource)
		->Iterations(30000)->ThreadRange(1, l_max_threads)->UseRealTime();


	FE_REGISTER_CONCURRENT_BENCHMARK(new_delete_random_size_concurrent_test)
		->Iterations(10000)->ThreadRange(1, l_max_threads)->UseRealTime();

#if FE_HAS_TBB_SCALABLE_MEMORY_RESOURCE
	FE_REGISTER_CONCURRENT_BENCHMARK(tbb_scalable_memory_resource_random_size_concurrent_test)
		->Iterations(10000)->ThreadRange(1, l_max_threads)->UseRealTime();
#endif

	FE_REGISTER_CONCURRENT_BENCHMARK(std_pmr_synchronized_pool_resource_random_size_concurrent_test)
		->Setup(setup_synchronized_pool_resource)->Teardown(teardown_synchronized_pool_resource)
		->Iterations(10000)->ThreadRange(1, l_max_threads)->UseRealTime();

	FE_REGISTER_CONCURRENT_BENCHMARK(FE_CMR_random_size_concurrent_test)
		->Setup(setup_concurrent_memory_resource)->Teardown(teardown_concurrent_memory_resource)
		->Iterations(10000)->ThreadRange(1, l_max_threads)->UseRealTime();


	FE_REGISTER_CONCURRENT_BENCHMARK(new_delete_random_size_accumulation_concurrent_test)
		->Iterations(1000)->ThreadRange(1, l_max_threads)->UseRealTime();

#if FE_HAS_TBB_SCALABLE_MEMORY_RESOURCE
	FE_REGISTER_CONCURRENT_BENCHMARK(tbb_scalable_memory_resource_random_size_accumulation_concurrent_test)
		->Iterations(1000)->ThreadRange(1, l_max_threads)->UseRealTime();
#endif

	FE_REGISTER_CONCURRENT_BENCHMARK(std_pmr_synchronized_pool_resource_random_size_accumulation_concurrent_test)
		->Setup(setup_synchronized_pool_resource)->Teardown(teardown_synchronized_pool_resource)
		->Iterations(1000)->ThreadRange(1, l_max_threads)->UseRealTime();

	FE_REGISTER_CONCURRENT_BENCHMARK(FE_CMR_random_size_accumulation_concurrent_test)
		->Setup(setup_concurrent_memory_resource)->Teardown(teardown_concurrent_memory_resource)
		->Iterations(1000)->ThreadRange(1, l_max_threads)->UseRealTime();
}

#undef FE_REGISTER_CONCURRENT_BENCHMARK